using System.Numerics;
using System.Text.Json;
using FighterPort.Core;

internal static class RetargetChecks
{
    public static async Task RunAsync(FighterProject original,Scene alternate,string directory,Action<bool,string> check)
    {
        var targetBones=alternate.Bones.Select((b,i)=>i is 11 or 14?b with{Rest=b.Rest with{Translation=b.Rest.Translation*.6f}}:i is 12 or 15?b with{Rest=b.Rest with{Translation=b.Rest.Translation*1.1f}}:b).ToArray();
        var targetScene=alternate with{Bones=targetBones};var target=original with{Id=Guid.NewGuid(),Scene=targetScene,Clips=[]};var a=SurfaceContactChecks.Profile(original.Scene);var b=SurfaceContactChecks.Profile(targetScene);
        var sourceLocal=original.Scene.Bones.Select(bone=>bone.Rest).ToArray();foreach(var c in a.Chains)sourceLocal[c.Middle]=sourceLocal[c.Middle] with{Rotation=new(c.Role.StartsWith("Foot",StringComparison.Ordinal)?20:0,0,c.Role.StartsWith("Hand",StringComparison.Ordinal)?35:0)};
        var tracks=sourceLocal.Select((t,i)=>new BoneTrack(original.Scene.Bones[i].Name,t.Channels().Select(v=>(Curve?)new Curve([new(0,v),new(23,v)])).ToArray())).ToArray();
        var clip=new AnimationClip(Guid.NewGuid(),"Original support / ledge",24,new(60),false,tracks);var sourcePose=AnimationService.Evaluate(original.Scene,clip,0);var pins=a.Chains.Select(c=>ContactSolver.Capture(original.Scene,sourcePose,a,c.Role,c.Role.StartsWith("Hand",StringComparison.Ordinal)?"Ledge":"Floor")).ToArray();
        var donor=original with{Clips=[clip],Contacts=[new ContactFrame(Guid.NewGuid(),clip.Id,0,a.SkeletonFingerprint,pins){EndFrame=7}]};var before=JsonSerializer.Serialize(donor,ProjectStore.Json);string targetHash=AnimationControls.DeformChecksum(targetScene);
        var result=RetargetService.Bake(donor,clip,a,target,b);check(result.Value is not null,"Proportion-aware transfer bakes an original motion onto a renamed rig with unequal arms/legs and different local axes: "+string.Join("; ",result.Diagnostics.Select(d=>d.Message)));var bake=result.Value!;
        check(bake.Clip.SampleCount==24&&bake.Clip.Rate==clip.Rate&&bake.Clip.Loop==clip.Loop,"Retargeting preserves source sample count, timebase and native loop metadata");
        check(bake.Contacts.Length==1&&bake.Contacts[0].EndFrame==7&&bake.MaximumContactError<.001f,"Retargeted hand/ledge and foot contacts use the shared solver and explicit release interval");
        var corrected=AnimationService.Evaluate(targetScene,bake.Clip,3.25);check(bake.Contacts[0].Pins.All(p=>Vector3.Distance(Vector3.Transform(p.LocalPoint,corrected.World[p.Bone]),p.Position)<.001f),"Protected fractional samples retain planted hand/foot anchors inside a constant support interval");
        var release=AnimationService.Evaluate(targetScene,bake.Clip,12);check(bake.Contacts.All(c=>!c.Contains(12)),"Contact release permits the target to leave support for get-up or airborne phases");
        var feet=pins.Where(p=>p.Role.StartsWith("Foot.",StringComparison.Ordinal)).ToArray();var hands=pins.Where(p=>p.Role.StartsWith("Hand.",StringComparison.Ordinal)).ToArray();
        var staggered=donor with{Contacts=[new(Guid.NewGuid(),clip.Id,0,a.SkeletonFingerprint,feet){EndFrame=23},new(Guid.NewGuid(),clip.Id,0,a.SkeletonFingerprint,hands){EndFrame=7}]};
        var staggeredBake=RetargetService.Bake(staggered,clip,a,target,b);var freeFk=RetargetService.Bake(staggered,clip,a,target,b,useContacts:false).Value!;
        check(staggeredBake.Value is not null,"Hands can release while the same motion retains its independent hard foot contacts");
        var afterRelease=AnimationService.Evaluate(targetScene,staggeredBake.Value!.Clip,17.375);var expectedFree=AnimationService.Evaluate(targetScene,freeFk.Clip,17.375);
        check(b.Chains.Where(c=>c.Role.StartsWith("Hand.",StringComparison.Ordinal)).SelectMany(c=>new[]{c.Root,c.Middle,c.Effector}).All(i=>Math.Abs(Quaternion.Dot(PoseGeometry.Rotation((Transform.Identity with{Rotation=afterRelease.Local[i].Rotation}).Matrix),PoseGeometry.Rotation((Transform.Identity with{Rotation=expectedFree.Local[i].Rotation}).Matrix)))>.999999f),"Released arms recover their source-driven FK articulation while feet stay constrained, without carrying old limb corrections");
        var moving=clip with{Id=Guid.NewGuid(),Tracks=tracks.Select((t,i)=>i==0?t with{Channels=t.Channels.Select((c,ch)=>ch==7?new Curve([new(0,0),new(7,0),new(8,.1f),new(23,.1f)]):c).ToArray()}:t).ToArray()};
        var movingSource=donor with{Clips=[moving],Contacts=donor.Contacts.Select(c=>c with{Clip=moving.Id}).ToArray()};var movingBake=RetargetService.Bake(movingSource,moving,a,target,b).Value!;
        check(new[]{0.25,3.25,6.25,6.75,7.0}.All(f=>{var p=AnimationService.Evaluate(targetScene,movingBake.Clip,f);return movingBake.Contacts[0].Pins.All(pin=>Vector3.Distance(Vector3.Transform(pin.LocalPoint,p.World[pin.Bone]),pin.Position)<.001f);}),"Moving release cannot contaminate protected fractional contact samples before the interval endpoint");
        var airborne=AnimationService.Evaluate(targetScene,movingBake.Clip,8);check(airborne.World[0].Translation.Y>.05f&&movingBake.Contacts.All(c=>!c.Contains(8)),"After an explicit hand/foot release, the baked motion retains the source body rise");
        var bind=AnimationService.Evaluate(targetScene,null,0);check(b.Chains.All(c=>Math.Abs(Vector3.Distance(release.World[c.Root].Translation,release.World[c.Middle].Translation)-Vector3.Distance(bind.World[c.Root].Translation,bind.World[c.Middle].Translation))<.0001f),"Retargeted FK/contact motion preserves target limb lengths rather than source proportions");
        var applied=RetargetService.Apply(target,bake);var doc=new EditorDocument(target);doc.Transaction("Retarget",p=>RetargetService.Apply(p,bake));doc.Undo();check(doc.Project.Clips.Length==0&&doc.Project.LibrarySources.Length==0,"Whole source-bound retarget import undoes in one transaction");doc.Redo();
        string file=Path.Combine(directory,"retargeted-support.fighterport");await ProjectStore.SaveAsync(applied,file);var reopened=await ProjectStore.LoadAsync(file);check(reopened.LibrarySources.Single().Clip.Revision==clip.Revision&&reopened.LibrarySources[0].Scene.SkeletonRevision==original.Scene.SkeletonRevision&&reopened.Clips[0].SourceSnapshot==reopened.LibrarySources[0].Id,"Save/reopen retains the independent target revision and immutable original source model/skeleton/clip");
        check(before==JsonSerializer.Serialize(donor,ProjectStore.Json)&&targetHash==AnimationControls.DeformChecksum(targetScene),"Transfer leaves donor data and target deform skeleton/weights unchanged");
        var reuse=RetargetService.Bake(applied,bake.Clip,b,original with{Clips=[]},a,useContacts:false).Value!;var reused=RetargetService.Apply(original with{Clips=[]},reuse);string ancestry=Path.Combine(directory,"retarget-source-ancestry.fighterport");await ProjectStore.SaveAsync(reused,ancestry);var ancestryReopened=await ProjectStore.LoadAsync(ancestry);
        check(ancestryReopened.LibrarySources.Length==2&&ancestryReopened.LibrarySources.Any(s=>s.Id==bake.Source.Id&&s.Clip.Revision==clip.Revision)&&ancestryReopened.LibrarySources.Single(s=>s.Id==reuse.Source.Id).Clip.SourceSnapshot==bake.Source.Id,"Reusing an already retargeted clip preserves its complete original source-model/clip ancestry through save/reopen");
        var spinTracks=new[]{new BoneTrack(original.Scene.Bones[0].Name,[null,null,null,null,new([new(0,0,30,30),new(23,690,30,30)]),null,new([new(0,0),new(23,2)]),null,null])};var spin=clip with{Id=Guid.NewGuid(),Tracks=spinTracks};var spinning=donor with{Clips=[spin],Contacts=[]};var spun=RetargetService.Bake(spinning,spin,a,target,b);
        check(spun.Value is not null&&Math.Abs(spun.Value.Clip.Tracks.Single(t=>t.Bone==targetScene.Bones[0].Name).Channels[4]!.Sample(23))>680,"Retarget baking preserves intentional multiple turns through continuous target Euler winding");
        var inPlace=RetargetService.Bake(spinning,spin,a,target,b,RootMotionPolicy.InPlace);check(inPlace.Value is not null&&AnimationService.Evaluate(targetScene,inPlace.Value.Clip,23).World[0].Translation.Length()<.0001f,"Root motion has an explicit in-place policy separate from limb proportion transfer");
        var held=clip with{Id=Guid.NewGuid(),Tracks=tracks.Select((track,i)=>i==7?track with{Channels=track.Channels.Select((curve,ch)=>(Curve?)new Curve([new(0,ch==5?0:sourceLocal[i].Channels()[ch]),new(10,ch==5?40:sourceLocal[i].Channels()[ch])],Interpolation.Step)).ToArray()}:track with{Channels=track.Channels.Select(c=>c! with{Interpolation=Interpolation.Step}).ToArray()}).ToArray()};
        var heldResult=RetargetService.Bake(donor with{Clips=[held],Contacts=[]},held,a,target,b);check(heldResult.Value is not null&&heldResult.Value.Clip.Tracks.SelectMany(t=>t.Channels.OfType<Curve>()).All(c=>c.Interpolation==Interpolation.Step),"Held artistic source poses stay stepped after target baking");
        var ambiguous=a with{SkeletonFingerprint="changed"};check(RetargetService.Bake(donor,clip,ambiguous,target,b).Value is null,"Changed or ambiguous source characterization blocks retargeting instead of guessing bone names");
    }
}
